def il(s):
    s = html.escape(str(s)); p = s.split('`')
    s = ''.join(f'<code>{x}</code>' if i % 2 else x for i, x in enumerate(p))
    s = re.sub(r'\*\*(.+?)\*\*', r'<b>\1</b>', s)
    return re.sub(r'\[(확인 필요[^\]]*|가정)\]', r'<span class="warn">[\1]</span>', s)


def md(s):
    """대화 원문의 간단한 마크다운(문단, - 목록, 들여쓴 목록, 1. 목록, 줄바꿈)을 HTML로."""
    out, stack = [], []
    def close(to=0):
        while len(stack) > to: out.append(f'</{stack.pop()}>')
    for line in str(s).split('\n'):
        m = re.match(r'^( *)(- |• |\d+\. )(.*)$', line)
        if m:
            lv = len(m.group(1)) // 2 + 1; tag = 'ol' if m.group(2)[0].isdigit() else 'ul'
            if len(stack) > lv: close(lv)
            while len(stack) < lv: out.append(f'<{tag}>'); stack.append(tag)
            out.append(f'<li>{il(m.group(3))}</li>')
        elif not line.strip():
            close()
        else:
            close(); out.append(f'<p>{il(line)}</p>')
    close()
    return '<div class="md">' + ''.join(out) + '</div>'


def one(c):
    """결정 하나의 본문 HTML (split.py가 결정별 PDF로 쓴다)."""
    no, ti, tg, why, ex, opts, rec, rs, sel, ans, ref = c
    chg = f'<div class="box" style="border-color:#c0392b"><b>변경 안내.</b> {il(CHANGED[no])}</div>' if no in CHANGED else ''
    rows = f'<tr><td>대상</td><td>{il(tg)}</td></tr><tr><td>무엇을 정하나</td><td>{md(why)}</td></tr>'
    if ex: rows += f'<tr><td>설명·예시</td><td>{md(ex)}</td></tr>'
    b = [chg + f'<h2 class="t">{no}. {il(ti)}</h2><table class="info">{rows}</table>',
         '<table><tr><th style="width:44px">선택지</th><th>방식</th><th>장점</th><th>단점</th></tr>']
    for (l, m, p, n) in opts:
        st = ' style="background:#e3eefb"' if l == sel else ''
        b.append(f'<tr{st}><td class="n"{" style=font-weight:700" if l == rec else ""}>{l}</td><td>{md(m)}</td><td>{md(p)}</td><td>{md(n)}</td></tr>')
    b.append(f'</table><div><b>추천: {rec}.</b></div>{md(rs)}' if rec else f'</table><div><b>추천 없음.</b></div>{md(rs)}')
    if sel != rec: b.append('<p><b>추천과 다른 선택이다.</b></p>')
    b.append(f'<table class="info"><tr><td>선택</td><td>{sel or "답변 전"}</td></tr><tr><td>사용자 답변</td><td>{il(ans)}</td></tr><tr><td>반영</td><td>{il(ref)}</td></tr></table>')
    return ''.join(b)
